"""Selection tests use synthetic fixtures; real evidence is generated by the CLI."""
import contextlib
import hashlib
import io
import json
from pathlib import Path
import sys
import tempfile
import unittest
from unittest.mock import patch

import numpy as np
import pandas as pd
from sklearn.linear_model import LinearRegression
from sklearn.feature_selection import RFE
from sklearn.preprocessing import StandardScaler

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'python/src'))
import feature_selection as fs
import startups_baseline as baseline
import verify_feature_selection as verifier


def fixture():
    rng = np.random.default_rng(918)
    frame = pd.DataFrame(rng.uniform(1, 100, size=(50, 3)), columns=baseline.NUMERIC)
    frame['State'] = ['A', 'B', 'C', 'A', 'B'] * 10
    frame['Profit'] = 5 + 2 * frame['R&D Spend'] - frame['Administration'] + rng.normal(0, 2, 50)
    return frame


class SelectorTests(unittest.TestCase):
    def test_real_algorithms_and_multialpha_cv_execute(self):
        frame = fixture().iloc[:40]
        with patch.object(fs, 'r_regression', wraps=fs.r_regression) as pearson, \
             patch.object(fs, 'f_regression', wraps=fs.f_regression) as ftest, \
             patch.object(fs.RFE, 'fit', autospec=True, side_effect=fs.RFE.fit) as rfe, \
             patch.object(fs.LassoCV, 'fit', autospec=True, side_effect=fs.LassoCV.fit) as lasso:
            _, trace = fs.fit_selectors(frame[baseline.FEATURES], frame['Profit'], 'test', [])
            self.assertEqual([pearson.call_count, ftest.call_count, rfe.call_count, lasso.call_count], [1, 1, 1, 1])
            self.assertEqual(len(lasso.call_args.args[0].alphas), 21)
            self.assertGreater(len(trace['details']['SFS']['steps'][0]['candidates']), 1)
        verifier.replay_lasso(trace, frame)

    def test_orders_and_subsets_match_computed_statistics(self):
        frame = fixture().iloc[:40]
        prepared, trace = fs.fit_selectors(frame[baseline.FEATURES], frame['Profit'], 'test', [])
        expected = RFE(LinearRegression(), n_features_to_select=1, step=1).fit(
            StandardScaler().fit_transform(prepared.values), frame['Profit'])
        for method, order in trace['orders'].items():
            self.assertEqual(set(order), set(prepared.names))
            for k in range(1, 6):
                self.assertEqual(trace['subsets'][method][str(k)], order[:k])
        self.assertEqual(trace['orders']['RFE'], sorted(prepared.names,
            key=lambda name: expected.ranking_[prepared.names.index(name)]))
        for method, key in [('Pearson', 'absolute_r'), ('F-Test', 'f_scores')]:
            computed = trace['details'][method][key]
            self.assertEqual(trace['orders'][method], sorted(prepared.names, key=lambda name: (-computed[name], name)))
        self.assertEqual(trace['details']['RFE']['elimination_order'], list(reversed(trace['orders']['RFE'][1:])))
        self.assertEqual(trace['details']['RFE']['survivor'], trace['orders']['RFE'][0])
        for step in trace['details']['SFS']['steps']:
            for candidate in step['candidates']:
                self.assertAlmostEqual(candidate['mean_rmse'], np.mean(candidate['fold_rmse']))
            self.assertEqual(step['chosen'], min(step['candidates'], key=lambda item: (item['mean_rmse'], item['added']))['added'])

    def test_sfs_responds_to_target_not_fixed_order(self):
        frame = fixture().iloc[:40]
        X = frame[baseline.FEATURES]
        prepared = fs.prepare(X, 'prep', [])
        first, _ = fs.sfs_rank(X, frame['R&D Spend'], prepared, 'first', [])
        second, _ = fs.sfs_rank(X, frame['Administration'], prepared, 'second', [])
        self.assertEqual(first[0], 'numeric__R&D Spend')
        self.assertEqual(second[0], 'numeric__Administration')
        self.assertNotEqual(first, second)

    def test_validation_values_do_not_fit_encoder_imputer_or_scaler(self):
        frame = fixture()
        X = frame.loc[:31, baseline.FEATURES].copy()
        X.loc[0, 'R&D Spend'] = np.nan
        audit = []
        prepared = fs.prepare(X, 'fit', audit)
        validation = frame.loc[32:, baseline.FEATURES].copy()
        validation['R&D Spend'] = 1e12
        validation['State'] = 'UNSEEN'
        before = json.dumps(audit)
        transformed = prepared.transform(validation)
        self.assertTrue(np.isfinite(transformed).all())
        self.assertNotIn('UNSEEN', audit[0]['state_categories'])
        self.assertAlmostEqual(audit[0]['numeric_medians'][0], X['R&D Spend'].median())
        self.assertEqual(before, json.dumps(audit))
        self.assertTrue((transformed[:, 3:] == 0).all())
        rare = X.copy()
        rare['State'] = 'A'
        with self.assertRaisesRegex(ValueError, 'three observed State'):
            fs.fit_selectors(rare, frame.loc[rare.index, 'Profit'], 'rare', [])

    def test_curves_use_actual_input_data(self):
        summary = []
        for method in fs.METHODS + ['All Features']:
            for k in ([5] if method == 'All Features' else range(1, 6)):
                summary.append({'method': method, 'k': k, 'rmse_mean': 20 + k,
                                'rmse_std': k / 10, 'r2_mean': .1 * k, 'r2_std': .01})
        captured = []
        def inspect_plot(path, figure):
            axis = figure.axes[0]
            metric = 'rmse' if path.stem.endswith('rmse') else 'r2'
            self.assertEqual(len(axis.containers), 5)
            for container in axis.containers:
                line = container.lines[0]
                np.testing.assert_array_equal(line.get_xdata(), range(1, 6))
                np.testing.assert_allclose(np.asarray(line.get_ydata(), dtype=float),
                    [20 + k if metric == 'rmse' else .1 * k for k in range(1, 6)])
            captured.append(path.name)
            baseline.plt.close(figure)
        with patch.object(baseline, 'save_plot', side_effect=inspect_plot):
            fs.plot_curves(summary, Path('/tmp'))
        self.assertEqual(len(captured), 2)


class SelectionIntegrationTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.temp = tempfile.TemporaryDirectory()
        cls.root = Path(cls.temp.name)
        cls.frame = fixture()
        cls.source = cls.root / 'synthetic.csv'
        cls.source.write_text(cls.frame.to_csv(index=False))
        cls.provenance = {'sha256': hashlib.sha256(cls.source.read_bytes()).hexdigest(), 'scope': 'synthetic fixture'}
        with contextlib.redirect_stdout(io.StringIO()):
            cls.directory = fs.run(cls.frame, cls.provenance, cls.root, 'first')
        cls.result = json.loads((cls.directory / 'results.json').read_text())

    @classmethod
    def tearDownClass(cls):
        cls.temp.cleanup()

    def test_independent_verifier_and_tampered_predictions(self):
        verifier.verify(self.directory, self.source, replay=True)
        path = self.directory / 'predictions.csv'
        original = path.read_bytes()
        try:
            data = pd.read_csv(path)
            data.loc[0, 'prediction'] += 1234
            data.to_csv(path, index=False)
            with self.assertRaises(ValueError):
                verifier.verify(self.directory, self.source)
        finally:
            path.write_bytes(original)

    def test_verifier_rejects_preprocessor_fitted_on_parent_fold(self):
        path = self.directory / 'results.json'
        original = path.read_bytes()
        altered = json.loads(original)
        entry = next(item for item in altered['audit'] if '/sfs/' in item['context'])
        parent = entry['context'].split('/sfs/')[0]
        entry['fit_row_ids'] = next(trace['fit_row_ids'] for trace in altered['traces'] if trace['context'] == parent)
        try:
            path.write_text(json.dumps(altered))
            with self.assertRaisesRegex(ValueError, 'exact inner training fold'):
                verifier.verify(self.directory, self.source)
        finally:
            path.write_bytes(original)

    def test_no_holdout_mutation_can_change_selection_or_curves(self):
        splits = json.loads((self.directory / 'splits.json').read_text())
        frame = self.frame.copy()
        frame.loc[splits['test_row_ids'], 'Profit'] += 1e6
        frame.loc[splits['test_row_ids'], 'R&D Spend'] += 1e10
        frame.loc[splits['test_row_ids'], 'State'] = 'HOLDOUT_ONLY'
        with contextlib.redirect_stdout(io.StringIO()):
            second = fs.run(frame, self.provenance, self.root, 'mutated')
        for name in ['results.json', 'predictions.csv', 'comparison.csv', 'plot_data.csv',
                     'selected_features.csv', 'final_selection.csv', 'frozen_selection.json',
                     'features_vs_rmse.png', 'features_vs_r2.png']:
            self.assertEqual((self.directory / name).read_bytes(), (second / name).read_bytes(), name)
        with self.assertRaises(FileExistsError):
            fs.run(frame, self.provenance, self.root, 'first')

    def test_all_features_matches_existing_baseline_cv(self):
        split = json.loads((self.directory / 'splits.json').read_text())
        X = self.frame.loc[split['train_row_ids'], baseline.FEATURES]
        y = self.frame.loc[split['train_row_ids'], 'Profit']
        for i, (fit, val) in enumerate(fs.folds(X, 5)):
            model = baseline.fit_checked(baseline.make_pipeline(), X.iloc[fit], y.iloc[fit])
            prediction, _ = baseline.predict_checked(model, X.iloc[val])
            actual = next(row for row in self.result['comparison']
                          if row['context'] == f'outer{i}' and row['method'] == 'All Features')
            self.assertAlmostEqual(actual['rmse'], baseline.metrics(y.iloc[val], prediction)['rmse'])
